+using Microsoft.AspNetCore.Components;
+
+namespace sv_41f0d04890974137b0cf528339455c5f.Services;
+
+/// <summary>
+/// Scoped service that owns the current theme state and pushes changes
+/// to all [CascadingParameter] subscribers via CascadingValueSource.
+/// One instance per circuit — each user gets independent state.
+/// </summary>
+public class ThemeService : IDisposable
+{
+    private readonly CascadingValueSource<ThemeInfo> _source;
+
+    public ThemeService(CascadingValueSource<ThemeInfo> source)
+    {
+        _source = source;
+    }
+
+    public ThemeInfo Current { get; private set; } = ThemeInfo.Default;
+
+    public event Action? OnChange;
+
+    public async Task SetThemeAsync(Theme theme)
+    {
+        Current = Current with { Theme = theme };
+        await NotifyAsync();
+    }
+
+    public async Task SetAccentColorAsync(string accentColor)
+    {
+        Current = Current with { AccentColor = accentColor };
+        await NotifyAsync();
+    }
+
+    public async Task SetAllAsync(Theme theme, string accentColor)
+    {
+        Current = new ThemeInfo(theme, accentColor);
+        await NotifyAsync();
+    }
+
+    private async Task NotifyAsync()
+    {
+        // Push to all [CascadingParameter] subscribers (crosses render mode boundaries)
+        await _source.NotifyChangedAsync(Current);
+        // Notify scoped event subscribers (components using @inject ThemeService)
+        OnChange?.Invoke();
