@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    // Belt-and-suspenders: also subscribe to the scoped event so we update
    // even if this component is in a context where cascading re-render
    // doesn't fire (e.g. static SSR after first interactive render).
    protected override void OnInitialized()
    {
        ThemeService.OnChange += OnThemeChanged;
    }

    private void OnThemeChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
    }
}

