@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService
@inject CascadingValueSource<ThemeInfo> ThemeSource
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Color Mode</label>
            <select class="form-select" value="@_selectedTheme" @onchange="OnThemeSelected">
                @foreach (var t in Enum.GetValues<Theme>())
                {
                    <option value="@t">@t</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color" class="form-control form-control-color"
                       value="@_accentColor" @onchange="OnAccentColorChanged" />
                <span>@_accentColor</span>
            </div>
        </div>

        <div class="mt-3 p-3 border rounded" style="border-color: @_accentColor !important;">
            <strong>Preview:</strong> @_selectedTheme mode with accent
            <span style="color: @_accentColor;">@_accentColor</span>
        </div>
    </div>
</div>

@code {
    private Theme _selectedTheme;
    private string _accentColor = ThemeInfo.Default.AccentColor;

    protected override void OnInitialized()
    {
        _selectedTheme = ThemeService.Current.Theme;
        _accentColor = ThemeService.Current.AccentColor;
        ThemeService.OnChange += OnExternalChange;
    }

    private async Task OnThemeSelected(ChangeEventArgs e)
    {
        if (Enum.TryParse<Theme>(e.Value?.ToString(), out var theme))
        {
            _selectedTheme = theme;
            await ThemeService.SetThemeAsync(theme);
        }
    }

    private async Task OnAccentColorChanged(ChangeEventArgs e)
    {
        _accentColor = e.Value?.ToString() ?? _accentColor;
        await ThemeService.SetAccentColorAsync(_accentColor);
    }

    private void OnExternalChange() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        ThemeService.OnChange -= OnExternalChange;
    }
}

